import { randomUUID } from 'node:crypto';

const MAX_PROMOS_PER_DAY = 3;
const MIN_PROMO_GAP_MS = 2 * 60 * 60 * 1000;
// Longest local day is 25h and zones differ by up to 26h, so 72h of history is enough to decide any rule.
const KEEP_MS = 72 * 60 * 60 * 1000;

const formatters = new Map();

// Returns a formatter for the zone, or null if the zone name is not valid.
function formatterFor(timeZone) {
  if (typeof timeZone !== 'string' || timeZone === '') return null;
  let f = formatters.get(timeZone);
  if (f === undefined) {
    try {
      f = new Intl.DateTimeFormat('en-US', {
        timeZone,
        calendar: 'gregory',
        numberingSystem: 'latn',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      });
    } catch {
      f = null;
    }
    formatters.set(timeZone, f);
  }
  return f;
}

function dayKey(formatter, ms) {
  let y = '', m = '', d = '';
  for (const p of formatter.formatToParts(ms)) {
    if (p.type === 'year') y = p.value;
    else if (p.type === 'month') m = p.value;
    else if (p.type === 'day') d = p.value;
  }
  return `${y}-${m}-${d}`;
}

export function createGate() {
  // userId -> array of { id, t } for promos that were allowed (and not cancelled)
  const promosByUser = new Map();
  // id -> userId, for cancel
  const owners = new Map();

  function deny(rule) {
    return { allowed: false, rule, id: null };
  }

  function request({ userId, timeZone, category, now } = {}) {
    // Security alerts are never limited by the promo policy and do not count toward it.
    if (category === 'security') {
      return { allowed: true, rule: '', id: randomUUID() };
    }
    if (category !== 'promo') return deny('invalid-category');

    const nowMs = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(nowMs)) return deny('invalid-time');
    if (typeof userId !== 'string' || userId === '') return deny('invalid-user');
    const fmt = formatterFor(timeZone);
    if (fmt === null) return deny('invalid-time-zone');

    let list = promosByUser.get(userId);
    if (list === undefined) {
      list = [];
      promosByUser.set(userId, list);
    }

    // Drop old entries.
    const kept = [];
    for (const rec of list) {
      if (rec.t >= nowMs - KEEP_MS) kept.push(rec);
      else owners.delete(rec.id);
    }
    list = kept;
    promosByUser.set(userId, list);

    const today = dayKey(fmt, nowMs);
    let countToday = 0;
    let tooClose = false;
    for (const rec of list) {
      if (dayKey(fmt, rec.t) === today) countToday++;
      if (Math.abs(nowMs - rec.t) < MIN_PROMO_GAP_MS) tooClose = true;
    }

    if (countToday >= MAX_PROMOS_PER_DAY) return deny('daily-cap');
    if (tooClose) return deny('min-gap');

    // The caller sends right away, so record the send now.
    const id = randomUUID();
    list.push({ id, t: nowMs });
    owners.set(id, userId);
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const userId = owners.get(id);
    if (userId === undefined) return; // unknown, security, already cancelled, or expired
    owners.delete(id);
    const list = promosByUser.get(userId);
    if (list === undefined) return;
    const i = list.findIndex((rec) => rec.id === id);
    if (i !== -1) list.splice(i, 1);
    if (list.length === 0) promosByUser.delete(userId);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-inv-d2-3/bot.mjs';

const D = (s) => new Date(s);
const req = (g, o) => g.request({ userId: 'u', timeZone: 'America/Los_Angeles', category: 'promo', ...o });

// cap 3/day, gap 2h. LA is UTC-8 on 2026-01-15: local midnight = 08:00Z
{
  const g = createGate();
  assert.equal(req(g, { now: D('2026-01-15T08:00:00Z') }).allowed, true);
  const r = req(g, { now: D('2026-01-15T09:59:59Z') });
  assert.deepEqual(r, { allowed: false, rule: 'min-gap', id: null });
  assert.equal(req(g, { now: D('2026-01-15T10:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: D('2026-01-15T12:00:00Z') }).allowed, true);
  const c = req(g, { now: D('2026-01-15T14:00:00Z') });
  assert.equal(c.rule, 'daily-cap');
  // still same local day at 07:59Z next UTC day
  assert.equal(req(g, { now: D('2026-01-16T07:59:00Z') }).rule, 'daily-cap');
  // next local day
  assert.equal(req(g, { now: D('2026-01-16T08:00:00Z') }).allowed, true);
}
// cancel frees slot; double/unknown cancel safe
{
  const g = createGate();
  const a = req(g, { now: D('2026-01-15T10:00:00Z') });
  assert.equal(req(g, { now: D('2026-01-15T10:30:00Z') }).rule, 'min-gap');
  g.cancel(a.id); g.cancel(a.id); g.cancel('nope'); g.cancel(undefined);
  assert.equal(req(g, { now: D('2026-01-15T10:30:00Z') }).allowed, true);
}
// security unlimited, uncounted, unique ids; users independent; zones differ
{
  const g = createGate();
  const ids = new Set();
  for (let i = 0; i < 10; i++) {
    const r = req(g, { category: 'security', now: D('2026-01-15T10:00:00Z') });
    assert.equal(r.allowed, true); assert.equal(r.rule, ''); ids.add(r.id);
  }
  assert.equal(ids.size, 10);
  g.cancel([...ids][0]);
  assert.equal(req(g, { now: D('2026-01-15T10:00:00Z') }).allowed, true);
  assert.equal(req(g, { userId: 'other', now: D('2026-01-15T10:00:00Z') }).allowed, true);
}
// zone-dependent day: 23:30 Berlin and 00:30 Berlin are different days but 1h apart (gap rule)
{
  const g = createGate();
  const tz = 'Europe/Berlin';
  const t = (s) => ({ timeZone: tz, now: D(s) });
  assert.equal(req(g, t('2026-01-15T00:30:00Z')).allowed, true); // 01:30 local
  assert.equal(req(g, t('2026-01-15T03:00:00Z')).allowed, true);
  assert.equal(req(g, t('2026-01-15T05:00:00Z')).allowed, true);
  assert.equal(req(g, t('2026-01-15T07:00:00Z')).rule, 'daily-cap');
  assert.equal(req(g, t('2026-01-15T23:00:00Z')).allowed, true); // 00:00 Jan 16 Berlin
}
// DST fall-back day in LA (2026-11-01 is 25h long)
{
  const g = createGate();
  assert.equal(req(g, { now: D('2026-11-01T07:00:00Z') }).allowed, true); // 00:00 PDT
  assert.equal(req(g, { now: D('2026-11-01T09:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: D('2026-11-01T11:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: D('2026-11-02T07:59:00Z') }).rule, 'daily-cap'); // 23:59 PST
  assert.equal(req(g, { now: D('2026-11-02T08:00:00Z') }).allowed, true);
}
// bad input denies, does not throw
{
  const g = createGate();
  assert.equal(req(g, { timeZone: 'Nope/Zone', now: D('2026-01-15T10:00:00Z') }).rule, 'invalid-time-zone');
  assert.equal(req(g, { now: new Date('x') }).rule, 'invalid-time');
  assert.equal(req(g, { category: 'x', now: D('2026-01-15T10:00:00Z') }).allowed, false);
}
